                       <button onClick={() => handleDelete(code.id)} className="text-red-500 hover:bg-red-50 p-2 rounded-lg transition-colors">
                         <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"></path></svg>
                       </button>
                    </td>
                  </tr>
                ))}
                {codes.length === 0 && (
                   <tr><td colSpan={5} className="py-10 text-center text-xs font-bold text-gray-400 uppercase italic">Chưa có mã nào</td></tr>
                )}
              </tbody>
            </table>
          </div>
        )}
      </div>

      {/* Create Modal */}
      {showModal && (
        <div className="fixed inset-0 bg-black/80 z-[100] flex items-center justify-center p-6 backdrop-blur-xl">
           <div className="bg-white dark:bg-gray-900 rounded-[2.5rem] p-10 w-full max-w-md shadow-2xl border border-white/10">
              <h3 className="text-xl font-black mb-8 text-gray-900 dark:text-white uppercase tracking-widest text-center">Tạo mã truy cập mới</h3>

              <div className="space-y-6">
                 <InputGroup label="Mã (Để trống để tự tạo)" icon="🎫">
                    <input type="text" className={`${baseInputClass} bg-gray-50 dark:bg-gray-800 border-gray-100 dark:border-gray-700 text-gray-900 dark:text-white font-bold pl-12`} value={newCode.value} onChange={e => setNewCode({...newCode, value: e.target.value.toUpperCase()})} placeholder="VD: SALE2024" />
                 </InputGroup>

                 <InputGroup label="Loại mã" icon="📑">
                    <select 
                        value={newCode.type} 
                        onChange={e => {
                          const type = e.target.value as CodeType;
                          setNewCode({
                            ...newCode, 
                            type, 
                            maxUses: type === CodeType.SINGLE ? 1 : type === CodeType.STATION ? 9999 : 5
                          });
                        }} 
                        className={`${baseInputClass} bg-gray-50 dark:bg-gray-800 border-gray-100 dark:border-gray-700 text-gray-900 dark:text-white font-bold pl-12 appearance-none`}
                    >
                       <option value={CodeType.SINGLE}>{t('admin.code.type.single', form)}</option>
                       <option value={CodeType.STATION}>{t('admin.code.type.station', form)}</option>
                       <option value={CodeType.TRIAL}>{t('admin.code.type.trial', form)}</option>
                    </select>
                 </InputGroup>

                 {newCode.type === CodeType.TRIAL && (
                    <InputGroup label="Số lần sử dụng tối đa" icon="🔢">
                        <input type="number" className={`${baseInputClass} bg-gray-50 dark:bg-gray-800 border-gray-100 dark:border-gray-700 text-gray-900 dark:text-white font-bold pl-12`} value={newCode.maxUses} onChange={e => setNewCode({...newCode, maxUses: Number(e.target.value)})} />
                    </InputGroup>
                 )}
              </div>

              <div className="flex justify-between gap-4 mt-12 pt-8 border-t border-gray-100 dark:border-gray-800">
                 <button onClick={() => setShowModal(false)} className="px-6 py-3 text-[11px] font-black uppercase tracking-widest text-gray-400">Hủy</button>
                 <button onClick={handleCreate} className="px-10 py-4 bg-brand-600 text-white font-black rounded-2xl shadow-xl uppercase tracking-widest">Tạo mã</button>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

